/* Mathematics practice for grade 8, levels 0–2. */
(()=>{for(let topic=0;topic<9;topic++)for(let level=0;level<3;level++)for(let i=0;i<14+(level!==topic%3?1:0)+(topic<4&&level===topic%3?1:0);i++){
 const n=i+2;let q,a,s,h;
 if(topic===0){h='Примени свойства арифметического квадратного корня.';if(level===0){q=`Вычисли √${n*n}.`;a=n;s=[`Поскольку ${n}² = ${n*n} и корень неотрицателен, ответ ${a}.`]}if(level===1){q=`Вычисли √${n*n*4} / 2.`;a=n;s=[`√${n*n*4} = ${2*n}.`,`${2*n}/2 = ${a}.`]}if(level===2){q=`Вычисли (√${(n+1)**2} − √${n*n})².`;a=1;s=[`Корни равны ${n+1} и ${n}.`,`Их разность равна 1; квадрат равен ${a}.`]} }
 if(topic===1){h='Разложи квадратный трёхчлен на множители или используй теорему Виета.';if(level===0){q=`Найди положительный корень уравнения x² = ${n*n}.`;a=n;s=[`Корни равны ±${n}, положительный корень — ${a}.`]}if(level===1){q=`Найди сумму корней уравнения x² − ${2*n+1}x + ${n*(n+1)} = 0.`;a=2*n+1;s=[`Трёхчлен равен (x − ${n})(x − ${n+1}).`,`Сумма корней: ${n} + ${n+1} = ${a}.`]}if(level===2){q=`Найди разность большего и меньшего корней уравнения x² − ${2*n+3}x + ${n*(n+3)} = 0.`;a=3;s=[`Уравнение раскладывается как (x − ${n})(x − ${n+3}) = 0.`,`Разность корней: ${n+3} − ${n} = ${a}.`]} }
 if(topic===2){h='Примени теорему Пифагора и внимательно определи катеты.';if(level===0){q=`Катеты прямоугольного треугольника равны ${3*n} и ${4*n}. Найди гипотенузу.`;a=5*n;s=[`c² = (${3*n})² + (${4*n})² = ${25*n*n}.`,`c = ${a}.`]}if(level===1){q=`Гипотенуза прямоугольного треугольника равна ${13*n}, один катет — ${5*n}. Найди другой катет.`;a=12*n;s=[`Второй катет в квадрате равен (${13*n})² − (${5*n})² = ${144*n*n}.`,`Его длина равна ${a}.`]}if(level===2){q=`Диагональ прямоугольника равна ${5*n}, одна сторона — ${3*n}. Найди площадь прямоугольника.`;a=12*n*n;s=[`Вторая сторона равна √((${5*n})²−(${3*n})²) = ${4*n}.`,`Площадь: ${3*n}·${4*n} = ${a}.`]} }
 if(topic===3){h='Разложи выражение на множители и учти область допустимых значений.';if(level===0){q=`Вычисли (${n}² − 1)/(${n} − 1).`;a=n+1;s=[`Числитель — разность квадратов: (${n}−1)(${n}+1).`,`Сокращаем ненулевой множитель и получаем ${a}.`]}if(level===1){q=`Вычисли (x² − ${n*n})/(x − ${n}) при x = ${n+2}.`;a=2*n+2;s=[`x²−${n*n} = (x−${n})(x+${n}); x ≠ ${n}.`,`Подстановка x = ${n+2} даёт ${n+2}+${n} = ${a}.`]}if(level===2){q=`Вычисли (x² − ${n*n})/(x + ${n}) при x = ${n+3}.`;a=3;s=[`Сократим множитель x+${n} при x ≠ −${n}: остаётся x−${n}.`,`При x=${n+3} получаем ${a}.`]} }
 if(topic===4){h='При решении неравенства учитывай направление знака.';if(level===0){q=`Сколько целых чисел x удовлетворяют неравенствам ${n} < x < ${n+5}?`;a=4;s=[`Подходят ${n+1}, ${n+2}, ${n+3}, ${n+4}. Всего ${a}.`]}if(level===1){q=`Найди наибольшее целое x, для которого 2x + ${n} < ${3*n+2}.`;a=n;s=[`2x < ${2*n+2}, то есть x < ${n+1}.`,`Наибольшее целое x = ${a}.`]}if(level===2){q=`Сколько целых x удовлетворяют −${n} ≤ x ≤ ${n}?`;a=2*n+1;s=[`От −${n} до −1 — ${n} чисел, от 1 до ${n} — ещё ${n}, а также есть 0.`,`Всего ${n}+${n}+1 = ${a}.`]} }
 if(topic===5){h='Используй свойства сторон и углов четырёхугольника.';if(level===0){q=`Стороны прямоугольника равны ${n} и ${n+3}. Найди периметр.`;a=4*n+6;s=[`Периметр равен 2(a+b).`,`2·(${n}+${n+3}) = ${a}.`]}if(level===1){q=`Один угол параллелограмма равен ${n+50}°. Найди соседний угол в градусах.`;a=130-n;s=[`Соседние углы параллелограмма в сумме дают 180°.`,`180 − ${n+50} = ${a}°.`]}if(level===2){q=`Периметр ромба равен ${4*n+16}. Найди длину его стороны.`;a=n+4;s=[`Все четыре стороны ромба равны.`,`Сторона равна ${4*n+16}/4 = ${a}.`]} }
 if(topic===6){h='Выбери соответствующую формулу площади и проверь высоту.';if(level===0){q=`Найди площадь треугольника с основанием ${2*n} и высотой 5.`;a=5*n;s=[`S = a·h/2 = ${2*n}·5/2 = ${a}.`]}if(level===1){q=`Основания трапеции равны ${n} и ${n+4}, высота равна 4. Найди площадь.`;a=4*n+8;s=[`S = (a+b)h/2.`,`S = (${n}+${n+4})·4/2 = ${a}.`]}if(level===2){q=`Диагонали ромба равны ${2*n} и ${2*n+4}. Найди площадь ромба.`;a=2*n*(n+2);s=[`Площадь ромба равна половине произведения диагоналей.`,`S = ${2*n}·${2*n+4}/2 = ${a}.`]} }
 if(topic===7){h='Используй перпендикулярность радиуса и касательной или свойство вписанного угла.';if(level===0){q=`Радиус окружности равен ${n}. Найди диаметр.`;a=2*n;s=[`Диаметр вдвое больше радиуса: 2·${n} = ${a}.`]}if(level===1){q=`Из точки P проведены касательные PA и PB к окружности. Если PA = ${n+3}, найди PB.`;a=n+3;s=[`Отрезки касательных из одной точки к окружности равны.`,`PB = PA = ${a}.`]}if(level===2){q=`Центральный угол AOB равен ${2*n+20}°. Найди вписанный угол ACB, опирающийся на ту же дугу AB, в градусах.`;a=n+10;s=[`Вписанный угол, опирающийся на ту же дугу, равен половине центрального.`,`∠ACB = ${2*n+20}/2 = ${a}°.`]} }
 if(topic===8){h='Укажи допустимые значения знаменателя и проверь найденный корень.';if(level===0){q=`Реши уравнение x/${n} = 3.`;a=3*n;s=[`Умножаем обе части на ${n}.`,`x = 3·${n} = ${a}.`]}if(level===1){q=`Реши уравнение ${n}/x = 1/2.`;a=2*n;s=[`ОДЗ: x ≠ 0. Перемножим крест-накрест: x = 2·${n}.`,`x = ${a}, условие x ≠ 0 выполнено.`]}if(level===2){q=`Реши уравнение (x + ${n})/(x − ${n}) = 3.`;a=2*n;s=[`ОДЗ: x ≠ ${n}. Получаем x + ${n} = 3(x − ${n}).`,`2x = ${4*n}, x = ${a}; он допустим.`]} }
 tasks.push({id:`grade8-practice-${topic}-${level}-${i}`,domain:'math',grade:8,subject:topicSubjects[`8-${topic}`],topic,topicName:curriculum[8][topic][0],level,title:['Базовая задача','Углублённая задача','Внешкольная задача'][level]+' · '+(i+1),question:q,answer:a,hints:[h,'Проверь полученный результат.'],steps:s,review:{plan:h,verify:s[s.length-1],trap:'Учти ограничения и единицы из условия.'},challenge:level===2,goal:'Понять ход решения'});
}})();
